// ENG-2341: discourse tag colours come from mark-level CSS variables, not a <style> element.
const NOTE = "tag-colours.md";

const plugin = (vault, json) => `app.plugins.plugins[${json(vault.pluginId)}]`;

// Opens NOTE containing the first tagged node type's tag; returns { tag, typeId, path }.
const openTaggedNote = async (ctx, { popout = false } = {}) => {
  const { client, json, vault } = ctx;
  const info = await client.evaluate(`const p = ${plugin(vault, json)};
    const i = p.settings.nodeTypes.findIndex((n) => n.tag);
    const n = p.settings.nodeTypes[i];
    return n ? { tag: n.tag, typeId: n.id, index: i } : null;`);
  if (!info) throw new Error("no node type with a tag in this vault");
  const path = await ctx.writeNote(NOTE, `First line\n\nSome claim #${info.tag}\n`);
  await client.evaluate(`return (async () => {
    const leaf = ${popout ? "app.workspace.openPopoutLeaf()" : `app.workspace.getLeaf("tab")`};
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(path)}), { state: { mode: "source" } });
    window.__dgVerifyLeaf = leaf;
    return true;
  })()`);
  await client.waitFor(
    `!!window.__dgVerifyLeaf?.view?.containerEl?.querySelector(".dg-discourse-tag .cm-hashtag")`,
    { label: "tag mark wraps .cm-hashtag" },
  );
  return info;
};

// Structure + computed colours of the tag chip in the verify leaf.
const probe = ({ client }) =>
  client.evaluate(`const root = window.__dgVerifyLeaf.view.containerEl;
    const doc = root.ownerDocument;
    const mark = root.querySelector(".dg-discourse-tag");
    const tags = Array.from(mark.querySelectorAll(".cm-hashtag"));
    const cs = (el) => doc.defaultView.getComputedStyle(el);
    const probeEl = doc.createElement("span");
    probeEl.style.backgroundColor = cs(mark).getPropertyValue("--dg-tag-bg").trim();
    probeEl.style.color = cs(mark).getPropertyValue("--dg-tag-fg").trim();
    doc.body.appendChild(probeEl);
    const want = { bg: cs(probeEl).backgroundColor, fg: cs(probeEl).color };
    probeEl.remove();
    return {
      isPopout: doc !== document,
      wrapsCount: tags.length,
      markInsideHashtag: !!mark.closest(".cm-hashtag"),
      text: mark.textContent,
      want,
      got: tags.map((t) => ({ bg: cs(t).backgroundColor, fg: cs(t).color, cursor: cs(t).cursor })),
      styleElements: Array.from(doc.querySelectorAll("style#dg-discourse-tag-colors")).length,
    };`);

const colourMatches = (r) =>
  r.wrapsCount >= 1 &&
  !r.markInsideHashtag &&
  r.got.every((g) => g.bg === r.want.bg && g.fg === r.want.fg && g.cursor === "pointer") &&
  r.styleElements === 0;

const closeLeaf = ({ client }) =>
  client.evaluate(`window.__dgVerifyLeaf?.detach(); delete window.__dgVerifyLeaf; return true;`);

export default [
  {
    name: "Tag mark wraps hashtag and paints node colour",
    input: "open a note containing a node type's #tag in source mode",
    expected: "dg-discourse-tag wraps both .cm-hashtag spans; their bg/fg equal the node type colours; no <style> element",
    run: async (ctx) => {
      await openTaggedNote(ctx);
      return probe(ctx);
    },
    expect: (r) => ({ pass: colourMatches(r), actual: JSON.stringify(r) }),
    teardown: closeLeaf,
  },
  {
    name: "Colours survive focus and scroll re-render",
    input: "put the cursor on the tag line, then scroll the editor away and back",
    expected: "same wrap and colours after CodeMirror re-renders the line",
    run: async (ctx) => {
      const { client } = ctx;
      await openTaggedNote(ctx);
      await client.evaluate(`const v = window.__dgVerifyLeaf.view;
        v.editor.focus(); v.editor.setCursor({ line: 2, ch: 3 });
        const s = v.editor.cm.scrollDOM; s.scrollTop = 99999; s.scrollTop = 0; return true;`);
      await new Promise((r) => setTimeout(r, 300));
      return probe(ctx);
    },
    expect: (r) => ({ pass: colourMatches(r), actual: JSON.stringify(r) }),
    teardown: closeLeaf,
  },
  {
    name: "Colour change repaints without reload",
    input: "set the node type colour to #12ab34 in memory and refresh editors",
    expected: "chip background becomes rgb(18, 171, 52); original colour restored in teardown",
    setup: async ({ client, json, vault }) =>
      client.evaluate(`const p = ${plugin(vault, json)};
        const n = p.settings.nodeTypes.find((x) => x.tag); return { id: n.id, color: n.color ?? null };`),
    run: async (ctx, state) => {
      const { client, json, vault } = ctx;
      await openTaggedNote(ctx);
      await client.evaluate(`const p = ${plugin(vault, json)};
        p.settings.nodeTypes.find((x) => x.id === ${json(state.id)}).color = "#12ab34";
        app.workspace.updateOptions(); return true;`);
      await client.waitFor(
        `getComputedStyle(window.__dgVerifyLeaf.view.containerEl.querySelector(".dg-discourse-tag .cm-hashtag")).backgroundColor === "rgb(18, 171, 52)"`,
        { label: "chip repainted" },
      );
      return probe(ctx);
    },
    expect: (r) => ({ pass: colourMatches(r) && r.want.bg === "rgb(18, 171, 52)", actual: JSON.stringify(r) }),
    teardown: async (ctx, state) => {
      const { client, json, vault } = ctx;
      await client.evaluate(`const p = ${plugin(vault, json)};
        const n = p.settings.nodeTypes.find((x) => x.id === ${json(state.id)});
        if (${json(state.color)} === null) delete n.color; else n.color = ${json(state.color)};
        app.workspace.updateOptions(); return true;`);
      await closeLeaf(ctx);
    },
  },
  {
    name: "Popout window gets tag colours",
    input: "open the tagged note in a popout window",
    expected: "popout chip coloured from styles.css + mark variables, with no generated <style>",
    run: async (ctx) => {
      await openTaggedNote(ctx, { popout: true });
      return probe(ctx);
    },
    expect: (r) => ({ pass: r.isPopout && colourMatches(r), actual: JSON.stringify(r) }),
    teardown: closeLeaf,
  },
];

export default {
  name: "Inspect tag line DOM",
  input: "open tagged note",
  expected: "dump",
  run: async (ctx) => {
    const { client, json, vault } = ctx;
    const info = await client.evaluate(`const p = app.plugins.plugins[${json(vault.pluginId)}];
      const n = p.settings.nodeTypes.find((x) => x.tag); return { tag: n?.tag, id: n?.id };`);
    const path = await ctx.writeNote("tag-colours.md", `First line\n\nSome claim #${info.tag}\n`);
    await client.evaluate(`return (async () => {
      const leaf = app.workspace.getLeaf("tab");
      await leaf.openFile(app.vault.getAbstractFileByPath(${json(path)}), { state: { mode: "source" } });
      window.__dgVerifyLeaf = leaf; return true; })()`);
    await new Promise((r) => setTimeout(r, 1500));
    return client.evaluate(`const root = window.__dgVerifyLeaf.view.containerEl;
      const lines = Array.from(root.querySelectorAll(".cm-line")).map((l) => l.outerHTML);
      const r = { info: ${json(info)}, lines };
      window.__dgVerifyLeaf.detach(); return r;`);
  },
  expect: (r) => ({ pass: true, actual: JSON.stringify(r) }),
};

